{
  "ref": "spec:openapi",
  "content": {
    "format": "openapi-3.1",
    "title": "TerraPulse Geospatial \u2014 a satellite imagery & field-analytics platform whose REST API serves crop-health rasters and field telemetry to agronomy SaaS partners. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the TerraPulse Geospatial \u2014 a satellite imagery & field-analytics platform whose REST API serves crop-health rasters and field telemetry to agronomy SaaS partners. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "TerraPulse Geospatial \u2014 a satellite imagery & field-analytics platform whose REST API serves crop-health rasters and field telemetry to agronomy SaaS partners. API",
        "version": "1.0.0",
        "description": "TerraPulse Partner API: OAuth2-protected endpoints for fetching field telemetry, imagery manifests, and tile-render jobs. Partners integrate it into their own dashboards via short-lived bearer tokens."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v2/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials token mint",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v1/oauth/token": {
          "post": {
            "summary": "DEPRECATED legacy token mint",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v2/fields": {
          "get": {
            "summary": "List partner fields",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/fields/{id}/telemetry": {
          "get": {
            "summary": "Field telemetry readings",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/imagery/manifest": {
          "get": {
            "summary": "Imagery manifest",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/render/jobs": {
          "post": {
            "summary": "Submit tile-render job (irreversible billing)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-07-02T08:55:54.006935+00:00"
}
